mapper.update:
UPDATE attendance_records
SET status_code    = #{statusCode},
    failure_reason = #{failureReason}
WHERE attendance_id = #{attendanceId}

mapper.select:
SELECT COUNT(*) FROM attendance_records
WHERE student_id = #{studentId}
  AND class_id   = #{classId}
  AND attendance_date = #{attendanceDate}

mapper.update:
UPDATE attendance_records
status_code = #{statusCode}, failure_reason = #{failureReason}, checked_at = #{checkedAt}, check_out_at = #{checkOutAt},
WHERE attendance_id = #{attendanceId}

mapper.select:
SELECT * FROM attendance_records
WHERE student_id = #{studentId}
  AND class_id   = #{classId}
  AND attendance_date = #{attendanceDate}
LIMIT 1

mapper.update:
UPDATE attendance_records
SET check_out_at = #{checkOutAt},
    status_code  = #{statusCode}
WHERE attendance_id = #{attendanceId}

mapper.select:
SELECT start_time AS startTime, end_time AS endTime
FROM classes
WHERE class_id = #{classId}

SELECT e.student_id
FROM enrollments e
WHERE e.class_id = #{classId}
  AND e.status_code = 'ACTIVE'
  AND NOT EXISTS (
      SELECT 1 FROM attendance_records ar
      WHERE ar.student_id = e.student_id
        AND ar.class_id   = e.class_id
        AND ar.attendance_date = #{date}
  )

SELECT class_name
FROM classes
WHERE class_id = #{classId}

SELECT user_id
FROM users
WHERE login_id = #{loginId}

SELECT COUNT(*)
FROM classes c
JOIN teachers t ON c.teacher_id = t.teacher_id
JOIN users    u ON t.user_id    = u.user_id
WHERE u.login_id = #{loginId}
  AND c.class_id = #{classId}

sql.where:
ar.class_id IN (
    SELECT c2.class_id FROM classes c2
    JOIN teachers t2 ON c2.teacher_id = t2.teacher_id
    JOIN users    u2 ON t2.user_id    = u2.user_id
    WHERE u2.login_id = #{loginId}
)
 AND ar.class_id = #{classId} 
 AND ar.attendance_date >= #{fromDate} 
 AND ar.attendance_date <= #{toDate}   
 AND u.name ILIKE '%' || #{keyword} || '%'

mapper.select:
SELECT COUNT(*)
FROM parents p
JOIN users pu           ON p.user_id     = pu.user_id
JOIN student_parents sp ON sp.parent_id  = p.parent_id
WHERE pu.login_id = #{loginId}
  AND sp.student_id = #{studentId}
